// Cloudflare Worker entry: the OpenNext-built Next.js app, plus a Cron Trigger
// that flushes the email outbox every minute through the app's internal route.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; APP_ORIGIN?: string };

export default {
  fetch: handler.fetch,
  async scheduled(
    _controller: unknown,
    env: Env,
    ctx: { waitUntil(promise: Promise<unknown>): void },
  ) {
    if (!env.CRON_SECRET) return;
    const origin = env.APP_ORIGIN || "https://watchguy.invalid";
    const request = new Request(origin + "/api/internal/mail-flush", {
      method: "POST",
      headers: { authorization: "Bearer " + env.CRON_SECRET },
    });
    ctx.waitUntil(
      Promise.resolve(handler.fetch(request, env, ctx)).then(
        async (res: Response) => {
          if (!res.ok)
            console.error("mail flush", res.status, await res.text());
        },
      ),
    );
  },
};
